import catalogue from "./googleFonts.json";

// Every Google Font, most popular first. Generated by scripts/generate-google-fonts.mjs
// from Google's public catalogue, so no API key is needed. Loading a font through the
// css2 endpoint needs no key either.
export type GoogleFont = { family: string; category: string; weights: number[] };

export const GOOGLE_FONTS: GoogleFont[] = (catalogue as Array<[string, string, number[]]>).map(
  ([family, category, weights]) => ({ family, category, weights }),
);

const byFamily = new Map(GOOGLE_FONTS.map((font) => [font.family, font]));

export function findGoogleFont(family: string) {
  return byFamily.get(family);
}

const requested = new Set<string>();

/** Adds the stylesheet for a Google Font once. Unknown families are ignored. */
export function ensureGoogleFont(family: string) {
  const font = byFamily.get(family);
  if (!font || requested.has(family) || typeof document === "undefined") return;
  requested.add(family);
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = googleFontCssUrl(font);
  document.head.appendChild(link);
}

export function googleFontCssUrl(font: GoogleFont) {
  const name = encodeURIComponent(font.family).replace(/%20/g, "+");
  return `https://fonts.googleapis.com/css2?family=${name}:wght@${font.weights.join(";")}&display=swap`;
}
